export const SS14_DESTINY_RULES = {"season":"SS14","authorityScope":"ss14-site-deployment","generatedAt":"2026-11-10T08:18:52.950Z","sourceUrl":"https://tlidb.com/en/Destiny_Type","sourcePageSha256":"7deb94de6b9ffc9ed450b73959533d2f09a30a03a897f9d004d286af0f70469a","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"bffbf0a0f2e11afcc8704c225db48bec7f02ce97267080486313718ed1105212"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"0093e823912099d8bc338d0fe1e884b30d4b2493799c1d32a3da8c4eadbb12af"},"body":"There are 4 types of Common Destinies: Micro Fate, Medium Fate, Kismet, and Dual Kismet.\nMicro Fate\nA Micro Fate can replace 1 Micro Talent Node or be installed in a Micro Destiny Slot. Up to 9 can be installed in Micro Destiny Slots.\nMedium Fate\nA Medium Fate can replace 1 Micro Talent Node or be installed in a Medium Destiny Slot. Up to 4 can be installed in Medium Destiny Slots.\nKismet\nKismets are Legendary Medium Destinies that grant unique stats.\nDual Kismet\nDual Kismets are a special type of Legendary Medium Destiny that grant extremely powerful special stats but can only be activated by installing 2 of the same Dual Kismet at the same time. Each type of Dual Kismet can only be activated once.","curse":{"sourceUrl":"https://tlidb.com/en/Curse","sourcePageSha256":"6b802b6cd2468889c811719b1cb4c91e3084aa64d8f76b2cb3588ca80c2d5bc6","body":"Curse Skills inflict various negative effects on enemies to increase their damage taken.\nCurse Skills inflict various negative effects on enemies to increase their damage taken.\nCurse Skills are usually not accompanied by any actions.\nMax Curse\nEach unit can only inflict 1 type of Curse Skill effect on the same enemy count. This upper limit is affected by Quantity bonuses.\nAfter Curse Skill effects on enemies reach their upper limit, inflicting another type of Curse Skill effect will replace the earliest inflicted effect on the enemy.\nCurse Effect\nThe negative effect values provided by Curse Skills are affected by Curse Effect bonuses.\nNegative effect value = Base value x (1 + all non-additional bonus percentages) x (1 + additional bonus percentage 1) x (1 + additional bonus percentage 2)..."}};
